code.cpp:
class Solution {
public:
    int minAbsoluteDifference(vector<int>& nums, int x) {
        int n = nums.size();
        int ans = INT_MAX;
        set<int> s;
        for (int j = x; j < n; j++) {
            s.insert(nums[j - x]);
            auto it = s.lower_bound(nums[j]);
            if (it != s.end()) {
                ans = min(ans, *it - nums[j]);
            }
            if (it != s.begin()) {
                auto pit = prev(it);
                ans = min(ans, nums[j] - *pit);
            }
        }
        return ans;
    }
};
